function validate([root, u]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs a root.';
  const values = root.filter(v => v !== null);
  if (values.length > 100000) return 'The tree has at most 10^5 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Node values are whole numbers from 1 to 10^5.';
  if (new Set(values).size !== values.length) return 'Node values must be unique.';
  // Every non-null entry must hang under an existing node in level order.
  let slots = 1;
  for (let i = 0; i < root.length; i++) {
    if (i >= slots) return 'Every node must have a parent earlier in the level-order array.';
    if (root[i] !== null) slots += 2;
  }
  if (!values.includes(u)) return 'u must be the value of a node in the tree.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [values, u] = input;
  const root = kit.toTree(values);
  const result = solve(root, kit.findNode(root, u));
  if (result === null || result === undefined) return null;
  if (typeof result !== 'object' || kit.findNode(root, result.val) !== result) throw new Error('Return a node of the given tree, or null.');
  return result.val;
}

