function findNeartestRightNode(root, u) {
  // A pre-order walk meets the nodes of each depth from left to right; record them with their depths.
  const visits = [];
  const stack = [[root, 0]];
  while (stack.length) {
    const [node, depth] = stack.pop();
    visits.push([node, depth]);
    if (node.right) stack.push([node.right, depth + 1]);
    if (node.left) stack.push([node.left, depth + 1]);
  }
  const at = visits.findIndex(([node]) => node === u);
  const depth = visits[at][1];
  for (let k = at + 1; k < visits.length; k++) if (visits[k][1] === depth) return visits[k][0];
  return null;
}

