function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  // At most 999 nodes keeps the level-order array under 2,000 entries.
  const n = size === 'large' ? 900 + pick(100) : 1 + pick(12);
  const deep = rand() < 0.3;
  const span = size === 'large' ? 100000 : rand() < 0.5 ? 30 : 100000;
  const used = new Set();
  const fresh = () => {
    for (;;) {
      const v = 1 + pick(span);
      if (!used.has(v)) { used.add(v); return v; }
    }
  };
  const nodes = [{ val: fresh(), left: null, right: null, depth: 0 }];
  while (nodes.length < n) {
    // Deep trees grow from the newest nodes; bushy trees attach a child anywhere.
    const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(3))] : nodes[pick(nodes.length)];
    const side = rand() < 0.5 ? 'left' : 'right';
    if (parent[side]) continue;
    parent[side] = { val: fresh(), left: null, right: null, depth: parent.depth + 1 };
    nodes.push(parent[side]);
  }
  const root = [];
  const queue = [nodes[0]];
  const rightmost = new Map();
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    root.push(node ? node.val : null);
    if (node) {
      rightmost.set(node.depth, node);
      queue.push(node.left, node.right);
    }
  }
  while (root[root.length - 1] === null) root.pop();
  // Sometimes ask about the last node of a level, whose answer is null.
  const u = rand() < 0.25 ? [...rightmost.values()][pick(rightmost.size)].val : nodes[pick(n)].val;
  return [root, u];
}
